CREATE FUNCTION public.command_accounts() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT has_any_role(auth.uid(),ARRAY['hr_admin']::app_role[]) THEN RAISE EXCEPTION 'HR administrator permission required'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',full_name)) FROM profiles),'[]'::jsonb); END $$;
REVOKE ALL ON FUNCTION public.command_accounts() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_accounts() TO authenticated;
CREATE FUNCTION public.command_link_account(_officer uuid,_user uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT has_any_role(auth.uid(),ARRAY['hr_admin']::app_role[]) THEN RAISE EXCEPTION 'HR administrator permission required'; END IF; PERFORM pg_advisory_xact_lock(hashtext('command_link_account')); IF NOT EXISTS(SELECT 1 FROM officers WHERE id=_officer AND employment_status='Active') OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=_user) THEN RAISE EXCEPTION 'Active employee and existing account required'; END IF; IF EXISTS(SELECT 1 FROM officers WHERE id=_officer AND user_id IS NOT NULL AND user_id<>_user) THEN RAISE EXCEPTION 'Existing personnel account cannot be replaced'; END IF; IF EXISTS(SELECT 1 FROM officers WHERE user_id=_user AND id<>_officer) THEN RAISE EXCEPTION 'Account is already linked to another employee'; END IF; UPDATE officers SET user_id=_user WHERE id=_officer; END $$;
REVOKE ALL ON FUNCTION public.command_link_account(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_link_account(uuid,uuid) TO authenticated;
CREATE FUNCTION public.command_map_supply_item(_id uuid,_item uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; BEGIN IF NOT has_any_role(auth.uid(),ARRAY['storekeeper','procurement_admin']::app_role[]) THEN RAISE EXCEPTION 'Logistics or procurement administrator permission required'; END IF; SELECT * INTO r FROM supply_requests WHERE id=_id FOR UPDATE; IF NOT FOUND OR r.workflow_kind<>'Command' OR r.approval_status<>'Approved' OR r.collection_status<>'Purchase Required' OR r.stage>=8 OR r.item_id IS NOT NULL THEN RAISE EXCEPTION 'Approved unmapped shortage request required'; END IF; IF NOT EXISTS(SELECT 1 FROM inventory_items WHERE id=_item) THEN RAISE EXCEPTION 'Existing inventory item required'; END IF; IF EXISTS(SELECT 1 FROM purchase_orders p JOIN purchase_order_items l ON l.po_id=p.id WHERE p.procurement_request_id=r.procurement_id AND l.quantity_received>0) THEN RAISE EXCEPTION 'Map inventory before accepting delivery'; END IF; IF EXISTS(SELECT 1 FROM purchase_orders p JOIN purchase_order_items l ON l.po_id=p.id WHERE p.procurement_request_id=r.procurement_id AND (l.is_asset OR (l.inventory_item_id IS NOT NULL AND l.inventory_item_id<>_item))) THEN RAISE EXCEPTION 'Purchase lines must reference the selected stock item, not a capital asset'; END IF; UPDATE supply_requests SET item_id=_item,history=history||jsonb_build_object('action','inventory item mapped','actor_id',auth.uid(),'at',now(),'item_id',_item) WHERE id=_id; UPDATE purchase_order_items l SET inventory_item_id=_item FROM purchase_orders p WHERE l.po_id=p.id AND p.procurement_request_id=r.procurement_id; PERFORM command_supply_route(_id); END $$;
REVOKE ALL ON FUNCTION public.command_map_supply_item(uuid,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.command_map_supply_item(uuid,uuid) TO authenticated;
CREATE FUNCTION public.command_po_mapping_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE item uuid; BEGIN SELECT s.item_id INTO item FROM supply_requests s JOIN purchase_orders p ON p.procurement_request_id=s.procurement_id WHERE p.id=NEW.po_id AND s.workflow_kind='Command'; IF FOUND AND (item IS NULL OR NEW.inventory_item_id IS DISTINCT FROM item OR NEW.is_asset) THEN RAISE EXCEPTION 'Map the command supply request to an inventory item before creating or accepting purchase lines'; END IF; RETURN NEW; END $$;
CREATE TRIGGER command_po_mapping_guard BEFORE INSERT OR UPDATE ON public.purchase_order_items FOR EACH ROW EXECUTE FUNCTION public.command_po_mapping_guard();
CREATE OR REPLACE FUNCTION public.command_supply_evidence(_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r supply_requests; stock integer; demand integer; deliveries integer; budget numeric; lead numeric; BEGIN SELECT * INTO r FROM supply_requests WHERE id=_id; IF NOT FOUND OR auth.uid() IS NULL OR NOT (has_any_role(auth.uid(),ARRAY['commandant','dc_admin']::app_role[]) OR (r.approval_status='Pending' AND r.command_stage=5 AND r.command_chain->4->>'user_id'=auth.uid()::text)) THEN RAISE EXCEPTION 'Command decision evidence access denied'; END IF; SELECT quantity INTO stock FROM inventory_items WHERE id=r.item_id; SELECT coalesce(sum(quantity),0) INTO demand FROM supply_requests WHERE item_id=r.item_id AND id<>r.id AND stage<8 AND approval_status NOT IN ('Rejected','Returned'); SELECT coalesce(sum(greatest(l.quantity-l.quantity_received,0)),0) INTO deliveries FROM purchase_order_items l JOIN purchase_orders p ON p.id=l.po_id WHERE l.inventory_item_id=r.item_id AND p.status IN ('Approved','Sent','Partially Delivered'); SELECT sum(remaining_amount) INTO budget FROM budgets WHERE department=r.section_id AND status='Approved' AND fiscal_year=extract(year from current_date); SELECT avg(g.delivery_date-p.created_at::date) INTO lead FROM goods_received_notes g JOIN purchase_orders p ON p.id=g.po_id WHERE g.status='Approved' AND EXISTS(SELECT 1 FROM purchase_order_items l WHERE l.po_id=p.id AND l.inventory_item_id=r.item_id); RETURN jsonb_build_object('stock',coalesce(stock,0),'pending_demand',demand,'expected_deliveries',deliveries,'budget',budget,'lead_days',lead,'recommendation',CASE WHEN coalesce(stock,0)-demand>=r.quantity THEN 'APPROVE' WHEN coalesce(stock,0)+deliveries-demand>=r.quantity THEN 'DEFER' WHEN budget IS NOT NULL AND budget<=0 THEN 'REJECT' ELSE 'PROCURE' END); END $$;